--
-- ddl/13_seam_repository.sql -- CAPV_* seam over the CAP_H_* copies (REPOSITORY mode).
-- =====================================================================
-- GENERATED by repository/build.py from its source manifest and from
-- ddl/10_seam_local.sql. Do not edit: change the manifest or ddl/10 and run
--   python3 repository/build.py
--
-- A repository copies the DBA_HIST_* views ddl/10 reads from each registered
-- target (repository/cap_repo.sql pulls them over a DB link) into CAP_H_*
-- tables of the same shape. The seam views below are ddl/10's with every
-- dba_hist_<x> renamed cap_h_<x>, so both modes present the same CAPV_*
-- contract from one body; the notes on every view live in ddl/10.
--
SET DEFINE OFF

-- Copy tables, created on first install. A later install adds a column the
-- manifest gained; it never drops one, and never drops a table (the copies
-- outlive the targets' AWR retention).
DECLARE
    v_owner VARCHAR2(128) := SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA');
    PROCEDURE ensure(p_table VARCHAR2, p_cols SYS.ODCIVARCHAR2LIST) IS
        v_n   PLS_INTEGER;
        v_ddl VARCHAR2(4000);
    BEGIN
        SELECT COUNT(*) INTO v_n FROM all_tables
        WHERE  owner = v_owner AND table_name = UPPER(p_table);
        IF v_n = 0 THEN
            FOR i IN 1 .. p_cols.COUNT LOOP
                v_ddl := v_ddl || CASE WHEN i > 1 THEN ', ' END || p_cols(i);
            END LOOP;
            EXECUTE IMMEDIATE 'CREATE TABLE ' || p_table || ' (' || v_ddl || ')';
            RETURN;
        END IF;
        FOR i IN 1 .. p_cols.COUNT LOOP
            SELECT COUNT(*) INTO v_n FROM all_tab_columns
            WHERE  owner = v_owner AND table_name = UPPER(p_table)
              AND  column_name = UPPER(REGEXP_SUBSTR(p_cols(i), '^\S+'));
            IF v_n = 0 THEN
                EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD (' || p_cols(i) || ')';
            END IF;
        END LOOP;
    END ensure;
BEGIN
    ensure('cap_h_snapshot', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'instance_number NUMBER', 'snap_id NUMBER', 'startup_time TIMESTAMP(3)',
        'begin_interval_time TIMESTAMP(3)', 'end_interval_time TIMESTAMP(3)'));
    ensure('cap_h_tbspc_space_usage', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'snap_id NUMBER', 'tablespace_id NUMBER',
        'tablespace_size NUMBER', 'tablespace_maxsize NUMBER', 'tablespace_usedsize NUMBER'));
    ensure('cap_h_osstat', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'instance_number NUMBER', 'snap_id NUMBER',
        'stat_name VARCHAR2(64 CHAR)', 'value NUMBER'));
    ensure('cap_h_sys_time_model', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'instance_number NUMBER', 'snap_id NUMBER',
        'stat_name VARCHAR2(64 CHAR)', 'value NUMBER'));
    ensure('cap_h_con_sys_time_model', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'con_id NUMBER', 'instance_number NUMBER',
        'snap_id NUMBER', 'stat_name VARCHAR2(64 CHAR)', 'value NUMBER'));
    ensure('cap_h_resource_limit', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'instance_number NUMBER', 'snap_id NUMBER',
        'resource_name VARCHAR2(30 CHAR)', 'current_utilization NUMBER', 'max_utilization NUMBER', 'limit_value VARCHAR2(10 CHAR)'));
    ensure('cap_h_sysstat', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'instance_number NUMBER', 'snap_id NUMBER',
        'stat_name VARCHAR2(64 CHAR)', 'value NUMBER'));
    ensure('cap_h_con_sysstat', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'con_id NUMBER', 'instance_number NUMBER',
        'snap_id NUMBER', 'stat_name VARCHAR2(64 CHAR)', 'value NUMBER'));
    ensure('cap_h_parameter', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'instance_number NUMBER', 'snap_id NUMBER',
        'parameter_name VARCHAR2(64 CHAR)', 'value VARCHAR2(512 CHAR)'));
    ensure('cap_h_asm_diskgroup_stat', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'snap_id NUMBER', 'group_number NUMBER',
        'total_mb NUMBER', 'free_mb NUMBER'));
    ensure('cap_h_seg_stat', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'instance_number NUMBER', 'snap_id NUMBER',
        'ts# NUMBER', 'obj# NUMBER', 'dataobj# NUMBER', 'space_used_delta NUMBER',
        'space_allocated_delta NUMBER'));
    ensure('cap_h_tablespace', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'ts# NUMBER', 'tsname VARCHAR2(30 CHAR)',
        'contents VARCHAR2(30 CHAR)', 'block_size NUMBER'));
    ensure('cap_h_datafile', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'ts# NUMBER', 'block_size NUMBER'));
    ensure('cap_h_pdb_instance', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'pdb_name VARCHAR2(128 CHAR)'));
    ensure('cap_h_database_instance', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'db_name VARCHAR2(9 CHAR)'));
    ensure('cap_h_asm_diskgroup', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'group_number NUMBER', 'name VARCHAR2(128 CHAR)'));
    ensure('cap_h_seg_stat_obj', SYS.ODCIVARCHAR2LIST(
        'dbid NUMBER', 'con_dbid NUMBER', 'ts# NUMBER', 'obj# NUMBER',
        'dataobj# NUMBER', 'owner VARCHAR2(128 CHAR)', 'object_name VARCHAR2(128 CHAR)', 'subobject_name VARCHAR2(128 CHAR)',
        'object_type VARCHAR2(18 CHAR)', 'tablespace_name VARCHAR2(30 CHAR)'));
END;
/

-- One row per copied source: the finished pull statement and its bind shape.
CREATE OR REPLACE VIEW cap_repo_source AS
SELECT 1 AS seq, 'SNAPSHOT' AS source_name, 'F' AS kind, 'CAP_H_SNAPSHOT' AS copy_table,
       q'~INSERT INTO cap_h_snapshot (dbid, instance_number, snap_id, startup_time, begin_interval_time, end_interval_time)
           SELECT dbid, instance_number, snap_id, startup_time, begin_interval_time, end_interval_time
           FROM dba_hist_snapshot@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3~' AS pull_sql FROM dual
UNION ALL
SELECT 2 AS seq, 'TBSPC_SPACE_USAGE' AS source_name, 'F' AS kind, 'CAP_H_TBSPC_SPACE_USAGE' AS copy_table,
       q'~INSERT INTO cap_h_tbspc_space_usage (dbid, con_dbid, snap_id, tablespace_id, tablespace_size, tablespace_maxsize, tablespace_usedsize)
           SELECT dbid, con_dbid, snap_id, tablespace_id, tablespace_size, tablespace_maxsize, tablespace_usedsize
           FROM dba_hist_tbspc_space_usage@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3~' AS pull_sql FROM dual
UNION ALL
SELECT 3 AS seq, 'OSSTAT' AS source_name, 'F' AS kind, 'CAP_H_OSSTAT' AS copy_table,
       q'~INSERT INTO cap_h_osstat (dbid, con_dbid, instance_number, snap_id, stat_name, value)
           SELECT dbid, con_dbid, instance_number, snap_id, stat_name, value
           FROM dba_hist_osstat@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3 AND (stat_name IN ('BUSY_TIME','IDLE_TIME','IOWAIT_TIME','NUM_CPUS','NUM_CPU_CORES','PHYSICAL_MEMORY_BYTES'))~' AS pull_sql FROM dual
UNION ALL
SELECT 4 AS seq, 'SYS_TIME_MODEL' AS source_name, 'F' AS kind, 'CAP_H_SYS_TIME_MODEL' AS copy_table,
       q'~INSERT INTO cap_h_sys_time_model (dbid, con_dbid, instance_number, snap_id, stat_name, value)
           SELECT dbid, con_dbid, instance_number, snap_id, stat_name, value
           FROM dba_hist_sys_time_model@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3 AND (stat_name IN ('DB CPU','DB time','background cpu time'))~' AS pull_sql FROM dual
UNION ALL
SELECT 5 AS seq, 'CON_SYS_TIME_MODEL' AS source_name, 'F' AS kind, 'CAP_H_CON_SYS_TIME_MODEL' AS copy_table,
       q'~INSERT INTO cap_h_con_sys_time_model (dbid, con_dbid, con_id, instance_number, snap_id, stat_name, value)
           SELECT dbid, con_dbid, con_id, instance_number, snap_id, stat_name, value
           FROM dba_hist_con_sys_time_model@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3 AND (stat_name IN ('DB CPU','DB time','background cpu time'))~' AS pull_sql FROM dual
UNION ALL
SELECT 6 AS seq, 'RESOURCE_LIMIT' AS source_name, 'F' AS kind, 'CAP_H_RESOURCE_LIMIT' AS copy_table,
       q'~INSERT INTO cap_h_resource_limit (dbid, con_dbid, instance_number, snap_id, resource_name, current_utilization, max_utilization, limit_value)
           SELECT dbid, con_dbid, instance_number, snap_id, resource_name, current_utilization, max_utilization, limit_value
           FROM dba_hist_resource_limit@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3 AND (resource_name IN ('processes','sessions'))~' AS pull_sql FROM dual
UNION ALL
SELECT 7 AS seq, 'SYSSTAT' AS source_name, 'F' AS kind, 'CAP_H_SYSSTAT' AS copy_table,
       q'~INSERT INTO cap_h_sysstat (dbid, con_dbid, instance_number, snap_id, stat_name, value)
           SELECT dbid, con_dbid, instance_number, snap_id, stat_name, value
           FROM dba_hist_sysstat@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3 AND (stat_name = 'redo size')~' AS pull_sql FROM dual
UNION ALL
SELECT 8 AS seq, 'CON_SYSSTAT' AS source_name, 'F' AS kind, 'CAP_H_CON_SYSSTAT' AS copy_table,
       q'~INSERT INTO cap_h_con_sysstat (dbid, con_dbid, con_id, instance_number, snap_id, stat_name, value)
           SELECT dbid, con_dbid, con_id, instance_number, snap_id, stat_name, value
           FROM dba_hist_con_sysstat@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3 AND (stat_name = 'redo size')~' AS pull_sql FROM dual
UNION ALL
SELECT 9 AS seq, 'PARAMETER' AS source_name, 'F' AS kind, 'CAP_H_PARAMETER' AS copy_table,
       q'~INSERT INTO cap_h_parameter (dbid, con_dbid, instance_number, snap_id, parameter_name, value)
           SELECT dbid, con_dbid, instance_number, snap_id, parameter_name, value
           FROM dba_hist_parameter@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3 AND (parameter_name IN ('cpu_count','processes','sessions','db_recovery_file_dest_size','sga_target','sga_max_size','pga_aggregate_target','pga_aggregate_limit','memory_target'))~' AS pull_sql FROM dual
UNION ALL
SELECT 10 AS seq, 'ASM_DISKGROUP_STAT' AS source_name, 'F' AS kind, 'CAP_H_ASM_DISKGROUP_STAT' AS copy_table,
       q'~INSERT INTO cap_h_asm_diskgroup_stat (dbid, con_dbid, snap_id, group_number, total_mb, free_mb)
           SELECT dbid, con_dbid, snap_id, group_number, total_mb, free_mb
           FROM dba_hist_asm_diskgroup_stat@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3~' AS pull_sql FROM dual
UNION ALL
SELECT 11 AS seq, 'SEG_STAT' AS source_name, 'F' AS kind, 'CAP_H_SEG_STAT' AS copy_table,
       q'~INSERT INTO cap_h_seg_stat (dbid, con_dbid, instance_number, snap_id, ts#, obj#, dataobj#, space_used_delta, space_allocated_delta)
           SELECT dbid, con_dbid, instance_number, snap_id, ts#, obj#, dataobj#, space_used_delta, space_allocated_delta
           FROM dba_hist_seg_stat@{LINK}
           WHERE dbid = :1 AND snap_id > :2 AND snap_id <= :3~' AS pull_sql FROM dual
UNION ALL
SELECT 12 AS seq, 'TABLESPACE' AS source_name, 'D' AS kind, 'CAP_H_TABLESPACE' AS copy_table,
       q'~MERGE INTO cap_h_tablespace t
           USING (SELECT DISTINCT dbid, con_dbid, ts#, tsname, contents, block_size
                  FROM dba_hist_tablespace@{LINK}
                  WHERE dbid = :1) s
           ON (t.dbid = s.dbid AND DECODE(t.con_dbid, s.con_dbid, 1, 0) = 1 AND t.ts# = s.ts#)
           WHEN MATCHED THEN UPDATE SET t.tsname = s.tsname, t.contents = s.contents, t.block_size = s.block_size
           WHEN NOT MATCHED THEN INSERT (dbid, con_dbid, ts#, tsname, contents, block_size)
                VALUES (s.dbid, s.con_dbid, s.ts#, s.tsname, s.contents, s.block_size)~' AS pull_sql FROM dual
UNION ALL
SELECT 13 AS seq, 'DATAFILE' AS source_name, 'D' AS kind, 'CAP_H_DATAFILE' AS copy_table,
       q'~MERGE INTO cap_h_datafile t
           USING (SELECT DISTINCT dbid, con_dbid, ts#, block_size
                  FROM dba_hist_datafile@{LINK}
                  WHERE dbid = :1) s
           ON (t.dbid = s.dbid AND DECODE(t.con_dbid, s.con_dbid, 1, 0) = 1 AND t.ts# = s.ts# AND DECODE(t.block_size, s.block_size, 1, 0) = 1)
           WHEN NOT MATCHED THEN INSERT (dbid, con_dbid, ts#, block_size)
                VALUES (s.dbid, s.con_dbid, s.ts#, s.block_size)~' AS pull_sql FROM dual
UNION ALL
SELECT 14 AS seq, 'PDB_INSTANCE' AS source_name, 'D' AS kind, 'CAP_H_PDB_INSTANCE' AS copy_table,
       q'~MERGE INTO cap_h_pdb_instance t
           USING (SELECT DISTINCT dbid, con_dbid, pdb_name
                  FROM dba_hist_pdb_instance@{LINK}
                  WHERE dbid = :1) s
           ON (t.dbid = s.dbid AND DECODE(t.con_dbid, s.con_dbid, 1, 0) = 1 AND DECODE(t.pdb_name, s.pdb_name, 1, 0) = 1)
           WHEN NOT MATCHED THEN INSERT (dbid, con_dbid, pdb_name)
                VALUES (s.dbid, s.con_dbid, s.pdb_name)~' AS pull_sql FROM dual
UNION ALL
SELECT 15 AS seq, 'DATABASE_INSTANCE' AS source_name, 'D' AS kind, 'CAP_H_DATABASE_INSTANCE' AS copy_table,
       q'~MERGE INTO cap_h_database_instance t
           USING (SELECT DISTINCT dbid, db_name
                  FROM dba_hist_database_instance@{LINK}
                  WHERE dbid = :1) s
           ON (t.dbid = s.dbid AND DECODE(t.db_name, s.db_name, 1, 0) = 1)
           WHEN NOT MATCHED THEN INSERT (dbid, db_name)
                VALUES (s.dbid, s.db_name)~' AS pull_sql FROM dual
UNION ALL
SELECT 16 AS seq, 'ASM_DISKGROUP' AS source_name, 'D' AS kind, 'CAP_H_ASM_DISKGROUP' AS copy_table,
       q'~MERGE INTO cap_h_asm_diskgroup t
           USING (SELECT DISTINCT dbid, con_dbid, group_number, name
                  FROM dba_hist_asm_diskgroup@{LINK}
                  WHERE dbid = :1) s
           ON (t.dbid = s.dbid AND DECODE(t.con_dbid, s.con_dbid, 1, 0) = 1 AND t.group_number = s.group_number)
           WHEN MATCHED THEN UPDATE SET t.name = s.name
           WHEN NOT MATCHED THEN INSERT (dbid, con_dbid, group_number, name)
                VALUES (s.dbid, s.con_dbid, s.group_number, s.name)~' AS pull_sql FROM dual
UNION ALL
SELECT 17 AS seq, 'SEG_STAT_OBJ' AS source_name, 'S' AS kind, 'CAP_H_SEG_STAT_OBJ' AS copy_table,
       q'~MERGE INTO cap_h_seg_stat_obj t
           USING (SELECT DISTINCT dbid, con_dbid, ts#, obj#, dataobj#, owner, object_name, subobject_name, object_type, tablespace_name
                  FROM dba_hist_seg_stat_obj@{LINK}
                  WHERE dbid = :1
             AND (dbid, con_dbid, ts#, obj#, dataobj#) IN
                 (SELECT dbid, con_dbid, ts#, obj#, dataobj#
                  FROM dba_hist_seg_stat@{LINK}
                  WHERE dbid = :2 AND snap_id > :3 AND snap_id <= :4)) s
           ON (t.dbid = s.dbid AND DECODE(t.con_dbid, s.con_dbid, 1, 0) = 1 AND t.ts# = s.ts# AND t.obj# = s.obj# AND t.dataobj# = s.dataobj#)
           WHEN MATCHED THEN UPDATE SET t.owner = s.owner, t.object_name = s.object_name, t.subobject_name = s.subobject_name, t.object_type = s.object_type, t.tablespace_name = s.tablespace_name
           WHEN NOT MATCHED THEN INSERT (dbid, con_dbid, ts#, obj#, dataobj#, owner, object_name, subobject_name, object_type, tablespace_name)
                VALUES (s.dbid, s.con_dbid, s.ts#, s.obj#, s.dataobj#, s.owner, s.object_name, s.subobject_name, s.object_type, s.tablespace_name)~' AS pull_sql FROM dual;


CREATE OR REPLACE VIEW capv_snapshot AS
SELECT dbid                     AS dbid,
       dbid                     AS con_dbid,
       instance_number          AS instance_number,
       snap_id                  AS snap_id,
       begin_interval_time      AS begin_interval_time,
       end_interval_time        AS end_interval_time,
       startup_time             AS startup_time
FROM   cap_h_snapshot;

CREATE OR REPLACE VIEW capv_tbspc_usage AS
SELECT dbid                     AS dbid,
       con_dbid                 AS con_dbid,
       snap_id                  AS snap_id,
       tablespace_id            AS tablespace_id,
       tablespace_size          AS tablespace_size,      -- blocks
       tablespace_maxsize       AS tablespace_maxsize,   -- blocks; 0 = no autoextend
       tablespace_usedsize      AS tablespace_usedsize   -- blocks
FROM   cap_h_tbspc_space_usage;

CREATE OR REPLACE VIEW capv_tablespace AS
SELECT dbid                     AS dbid,
       con_dbid                 AS con_dbid,
       ts#                      AS tablespace_id,
       tsname                   AS tablespace_name,
       contents                 AS contents,            -- PERMANENT / UNDO / TEMPORARY
       block_size               AS block_size           -- bytes/block
FROM   cap_h_tablespace;

CREATE OR REPLACE VIEW capv_datafile AS
SELECT dbid                     AS dbid,
       con_dbid                 AS con_dbid,
       ts#                      AS tablespace_id,
       MAX(block_size)          AS block_size           -- bytes/block
FROM   cap_h_datafile
GROUP BY dbid, con_dbid, ts#;

CREATE OR REPLACE VIEW capv_osstat AS
SELECT dbid                     AS dbid,
       con_dbid                 AS con_dbid,
       instance_number          AS instance_number,
       snap_id                  AS snap_id,
       stat_name                AS stat_name,
       value                    AS value
FROM   cap_h_osstat
WHERE  stat_name IN ('BUSY_TIME','IDLE_TIME','IOWAIT_TIME',
                     'NUM_CPUS','NUM_CPU_CORES','PHYSICAL_MEMORY_BYTES');

CREATE OR REPLACE VIEW capv_time_model AS
SELECT c.dbid                   AS dbid,
       c.con_dbid               AS con_dbid,
       c.instance_number        AS instance_number,
       c.snap_id                AS snap_id,
       c.stat_name              AS stat_name,
       c.value                  AS value
FROM   cap_h_con_sys_time_model c
WHERE  c.stat_name IN ('DB CPU','DB time','background cpu time')
  AND  NVL(c.con_id, 0) <> 2
UNION ALL
SELECT s.dbid, s.con_dbid, s.instance_number, s.snap_id, s.stat_name, s.value
FROM   cap_h_sys_time_model s
WHERE  s.stat_name IN ('DB CPU','DB time','background cpu time')
  AND  NOT EXISTS (SELECT 1
                   FROM   cap_h_con_sys_time_model c
                   WHERE  c.dbid = s.dbid AND c.snap_id = s.snap_id
                     AND  c.instance_number = s.instance_number
                     AND  c.stat_name = s.stat_name);

CREATE OR REPLACE VIEW capv_container AS
SELECT k.dbid,
       k.con_dbid,
       d.db_name,
       p.con_name
FROM  (
        SELECT dbid, con_dbid FROM cap_h_pdb_instance
        UNION
        SELECT dbid, dbid FROM cap_h_database_instance
      ) k
LEFT  JOIN (SELECT dbid, MAX(db_name) AS db_name
            FROM   cap_h_database_instance
            GROUP  BY dbid) d
  ON  d.dbid = k.dbid
LEFT  JOIN (SELECT dbid, con_dbid, MAX(pdb_name) AS con_name
            FROM   cap_h_pdb_instance
            GROUP  BY dbid, con_dbid) p
  ON  p.dbid = k.dbid AND p.con_dbid = k.con_dbid;

CREATE OR REPLACE VIEW capv_resource_limit AS
SELECT dbid                     AS dbid,
       con_dbid                 AS con_dbid,
       instance_number          AS instance_number,
       snap_id                  AS snap_id,
       resource_name            AS resource_name,
       current_utilization      AS current_utilization,
       max_utilization          AS max_utilization,
       CASE WHEN REGEXP_LIKE(TRIM(limit_value), '^[0-9]+$')
            THEN TO_NUMBER(TRIM(limit_value))
       END                      AS limit_value
FROM   cap_h_resource_limit
WHERE  resource_name IN ('processes','sessions');

CREATE OR REPLACE VIEW capv_sysstat AS
SELECT c.dbid                   AS dbid,
       c.con_dbid               AS con_dbid,
       c.instance_number        AS instance_number,
       c.snap_id                AS snap_id,
       c.stat_name              AS stat_name,
       c.value                  AS value
FROM   cap_h_con_sysstat c
WHERE  c.stat_name = 'redo size'
  AND  NVL(c.con_id, 0) <> 2
UNION ALL
SELECT s.dbid, s.con_dbid, s.instance_number, s.snap_id, s.stat_name, s.value
FROM   cap_h_sysstat s
WHERE  s.stat_name = 'redo size'
  AND  NOT EXISTS (SELECT 1
                   FROM   cap_h_con_sysstat c
                   WHERE  c.dbid = s.dbid AND c.snap_id = s.snap_id
                     AND  c.instance_number = s.instance_number
                     AND  c.stat_name = s.stat_name);

CREATE OR REPLACE VIEW capv_parameter AS
SELECT dbid                     AS dbid,
       dbid                     AS con_dbid,
       instance_number          AS instance_number,
       snap_id                  AS snap_id,
       LOWER(parameter_name)    AS parameter_name,
       CASE WHEN REGEXP_LIKE(TRIM(value), '^[0-9]+$')
            THEN TO_NUMBER(TRIM(value))
       END                      AS value_num
FROM   cap_h_parameter
WHERE  parameter_name IN ('cpu_count','processes','sessions',
                          'db_recovery_file_dest_size',
                          'sga_target','sga_max_size',
                          'pga_aggregate_target','pga_aggregate_limit',
                          'memory_target')
  AND  NVL(con_dbid, dbid) = dbid;

CREATE OR REPLACE VIEW capv_asm_diskgroup AS
SELECT s.dbid                   AS dbid,
       s.dbid                   AS con_dbid,
       s.snap_id                AS snap_id,
       g.name                   AS group_name,
       s.total_mb               AS total_mb,
       s.free_mb                AS free_mb,
       CAST(NULL AS NUMBER)     AS usable_file_mb
FROM   cap_h_asm_diskgroup_stat s
JOIN   cap_h_asm_diskgroup g
  ON   g.dbid = s.dbid AND g.group_number = s.group_number
 AND   g.con_dbid = s.con_dbid;

CREATE OR REPLACE VIEW capv_seg_stat AS
SELECT s.dbid                   AS dbid,
       s.con_dbid               AS con_dbid,
       s.instance_number        AS instance_number,
       s.snap_id                AS snap_id,
       s.ts#                    AS tablespace_id,
       o.tablespace_name        AS tablespace_name,
       o.owner                  AS owner,
       o.object_name            AS object_name,
       o.subobject_name         AS subobject_name,
       o.object_type            AS object_type,
       s.space_used_delta       AS space_used_delta,
       s.space_allocated_delta  AS space_allocated_delta
FROM   cap_h_seg_stat s
JOIN   cap_h_seg_stat_obj o
  ON   o.dbid = s.dbid AND o.con_dbid = s.con_dbid
 AND   o.ts# = s.ts# AND o.obj# = s.obj# AND o.dataobj# = s.dataobj#;

CREATE OR REPLACE VIEW capv_contract AS
WITH src AS (
        SELECT 'SNAPSHOT' AS source_name, dbid, con_dbid, snap_id FROM capv_snapshot
        UNION ALL SELECT 'TBSPC_USAGE',    dbid, con_dbid, snap_id FROM capv_tbspc_usage
        UNION ALL SELECT 'OSSTAT',         dbid, con_dbid, snap_id FROM capv_osstat
        UNION ALL SELECT 'TIME_MODEL',     dbid, con_dbid, snap_id FROM capv_time_model
        UNION ALL SELECT 'SYSSTAT',        dbid, con_dbid, snap_id FROM capv_sysstat
        UNION ALL SELECT 'RESOURCE_LIMIT', dbid, con_dbid, snap_id FROM capv_resource_limit
        UNION ALL SELECT 'PARAMETER',      dbid, con_dbid, snap_id FROM capv_parameter
        UNION ALL SELECT 'ASM_DISKGROUP',  dbid, con_dbid, snap_id FROM capv_asm_diskgroup
        UNION ALL SELECT 'SEG_STAT',       dbid, con_dbid, snap_id FROM capv_seg_stat
     ),
     per_con AS (
        SELECT source_name, dbid, con_dbid,
               COUNT(*)     AS n_rows,
               MIN(snap_id) AS min_snap_id,
               MAX(snap_id) AS max_snap_id
        FROM   src
        GROUP  BY source_name, dbid, con_dbid
     ),
     snap_end AS (
        SELECT dbid, snap_id, MAX(end_interval_time) AS end_time
        FROM   capv_snapshot
        GROUP  BY dbid, snap_id
     ),
     sources AS (
        SELECT 'SNAPSHOT' AS source_name, 'N' AS per_container_expected FROM dual
        UNION ALL SELECT 'TBSPC_USAGE',    'Y' FROM dual
        UNION ALL SELECT 'OSSTAT',         'N' FROM dual
        UNION ALL SELECT 'TIME_MODEL',     'Y' FROM dual
        UNION ALL SELECT 'SYSSTAT',        'Y' FROM dual
        UNION ALL SELECT 'RESOURCE_LIMIT', 'N' FROM dual
        UNION ALL SELECT 'PARAMETER',      'N' FROM dual
        UNION ALL SELECT 'ASM_DISKGROUP',  'N' FROM dual
        UNION ALL SELECT 'SEG_STAT',       'Y' FROM dual
     )
SELECT k.source_name,
       NVL(SUM(p.n_rows), 0)        AS n_rows,
       COUNT(DISTINCT p.con_dbid)   AS n_con_dbid,
       MIN(p.min_snap_id)           AS min_snap_id,
       MAX(p.max_snap_id)           AS max_snap_id,
       MAX(e.end_time)              AS max_end_time,
       k.per_container_expected
FROM   sources k
LEFT   JOIN per_con p
  ON   p.source_name = k.source_name
LEFT   JOIN snap_end e
  ON   e.dbid = p.dbid AND e.snap_id = p.max_snap_id
GROUP  BY k.source_name, k.per_container_expected;

@@repository/cap_repo.sql
